source_raw_tex:
\eqalign{L^p_{\Bbb C}=L^p_{\Bbb C}(\mu)
&=\{f^{\ssbullet}:f\in\eusm L^p_{\Bbb C}\}\cr
&=\{u:u\in L^0_{\Bbb C}(\mu),\,\Real(u)\in L^p(\mu)\text{ and }
\Imag(u)\in L^p(\mu)\}\cr
&=\{u:u\in L^0_{\Bbb C}(\mu),\,|u|\in L^p(\mu)\}.\cr}

